    try {
        scwin.popupBatchApplExcelUpload()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90011.btn_popupBatchApplExcelUpload_onclick' }); }
};

/**
 * @method
 * @name frnList_oncellclick
 * @description frnList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.frnList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: focus_tr (인자 미해석) */
        /* TODO Stage2: 행 동작 미정의: scwin.detail (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.detail'); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'frnList.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_FrnIntDecl
 * @description Frn Int Decl 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FrnIntDecl = async function () {
    const sbmOptions = {
        id: "tx_fn_FrnIntDecl",
        method: "post",
        action: "/event/event.do",
        ref: "dma_FrnIntDeclReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

