///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name __on_enter_3_ipt_searchword
 * @description on enter 3 ipt searchword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_3_ipt_searchword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.searchList() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf90011.__on_enter_3_ipt_searchWord' }); }
};

/**
 * @method
 * @name focus_tr
 * @description focus tr 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.focus_tr = function (obj) {
    let i;
    const tabNum = obj.parentNode.children.length;
    for (i = 0; i < tabNum; i++) {
        obj.parentNode.children[i].className = '';
    }
    obj.className = 'on';
    scwin.setSelectedVal();
};

/**
 * @method
 * @name setSelectedVal
 * @description set Selected Val 처리
 * @returns {void}
 * @hidden N
 */
scwin.setSelectedVal = function () {
    const selectedIndex = scwin.getSelectedIndex();
    const table = $c.util.getComponent("frnList");
    const row = table.rows[selectedIndex];
    if (row) {
        const rowData = Array.from(row.cells).map(function(cell) {
                return cell.textContent;
        });
        $c.util.getComponent('ipt_stdCd').setValue(rowData[1].trim());
        $c.util.getComponent('ipt_isuNm').setValue(rowData[2].trim());
        $c.util.getComponent('ipt_intRtChgSeq').setValue(rowData[6].trim());
        $c.util.getComponent('ipt_intRtChgDd').setValue(rowData[7].trim());
        $c.util.getComponent('ipt_intPayDd').setValue(rowData[8].trim());
    }
};

/**
 * @method
 * @name getSelectedIndex
 * @description get Selected Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.getSelectedIndex = function () {
    const rows = document.querySelectorAll("#frnList tr");
    let selectedIndex = -1;
    rows.forEach(function(row, index) {
            if (row.classList.contains("on")) {
                selectedIndex = index;
            }
    });
    return selectedIndex;
};

/**
 * @method
 * @name frnIntDecl
 * @description frn Int Decl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.frnIntDecl = async function () {
    const selectedIndex = scwin.getSelectedIndex();
    if (selectedIndex < 0) {
        await $c.win.alert("FRN금리 변경신고 대상 종목을 선택하세요.");
        return;
    }
    const message = "[" + $c.util.getComponent('ipt_isuNm').getValue() + "]\n" + "FRN금리 변경 신고하시겠습니까?";
    if (!await $c.win.confirm(message)) {
        return;
    }
    const frm = (document.SearchForm || { elements: [] });
    frm.action = '/event/event.do';
    $c.util.getComponent("dma_FrnIntDeclReq").set("method", 'floatingRateView');
    frm.target = '_self';
    await scwin.tx_fn_FrnIntDecl();
};

/**
 * @method
 * @name manageSchedule
 * @description manage Schedule 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.manageSchedule = async function () {
    const selectedIndex = scwin.getSelectedIndex();
    if (selectedIndex < 0) {
        await $c.win.alert("일정변경 대상 종목을 선택하세요.");
        return;
    }
    const message = "[" + $c.util.getComponent('ipt_isuNm').getValue() + "]\n" + "표면이자율 결정 일정을 변경하시겠습니까?";
    if (!await $c.win.confirm(message)) {
        return;
    }
    const frm = (document.SearchForm || { elements: [] });
    frm.action = "/event/event.do";
    $c.util.getComponent("dma_FrnIntDeclReq").set("method", "frnScheduleView");
    frm.target = "_self";
    await scwin.tx_fn_manageSchedule();
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    const frm = (document.SearchForm || { elements: [] });
    $c.util.getComponent("dma_FrnIntDeclReq").set("method", "searchIsuInfoChgList");
    frm.action = '/common/IsuInfoChgSearch.do';
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name popupBatchApplExcelUpload
 * @description popup Batch Appl Excel Upload 처리
 * @returns {void}
 * @hidden N
 */
scwin.popupBatchApplExcelUpload = function () {
    const width = 1040;
    const height = 520;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    const win = $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })('/common/common.do?method=popupBatchApplExcelUpload&bnd_mktact_tp_cd=' + $c.util.getComponent("dma_FrnIntDeclReq").get("bndMktactTpCd")), { id: "detail", scrollbars: true, resizable: true, type: "pageFramePopup" }, {});
};

/**
 * @method
 * @name fnExcelDown
 * @description fn Excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnExcelDown = async function () {
    await $c.win.alert("다운로드는 데이터에 따라 몇초에서 몇분가량 소요될 수 있습니다.");
    const frm = (document.SearchForm || { elements: [] });
    frm.action = "/common/IsuInfoChgSearch.do";
    $c.util.getComponent("dma_FrnIntDeclReq").set("method", "downExcelFrnList");
    frm.target = "iframeExcel";
    await scwin.tx_fnExcelDown();
};

/**
 * @method
 * @name krxpage_pagenavigator_112_onclick
 * @description krxpage_pagenavigator_112 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_112_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_FrnIntDeclReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_112.page' }); } await scwin.searchList(); };
